```python
def count_divisors(n):
    if not isinstance(n, int) or n < 1:
        raise ValueError('n must be a positive integer')
    count = 0
    for d in range(1, int(n ** 0.5) + 1):
        if n % d == 0:
            if d * d == n:
                count += 1
            else:
                count += 2
    return count
